def lru_cache(maxsize=128, typed=False):
    def decorator(func):
        cache = {}
        max_size = maxsize
        cur_size = 0

        def wrapper(*args, **kwargs):
            key = make_key(args, kwargs, typed)
            if key in cache:
                result = cache[key]
            else:
                result = func(*args, **kwargs)
                if cur_size >= max_size:
                    # Remove the least recently used key
                    cache.pop(list(cache.keys())[0])
                    cur_size -= 1
                cache[key] = result
                cur_size += 1
            return result
        return wrapper
    return decorator

