def difference(d1, d2, level=-1):
    """
    Returns a dictionary with items from d1 not contained in d2.

    :param d1: The first dictionary.
    :param d2: The second dictionary.
    :param level: The maximum depth of recursion. For infinite recursion, set this to -1. For level 1, if a key is present both in d1 and d2 but has different values, it is included into the difference. See :func:`intersection` for more details.
    :returns: A dictionary with items from d1 not contained in d2.
    """
    result = {}
    for key, value in d1.items():
        if key not in d2 or value != d2[key]:
            result[key] = value
    for key, value in d2.items():
        if key not in d1 or value != d1[key]:
            result[key] = value
    return result
