def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    return list(map(self.apply_absorption, args))

def apply_absorption(self, expr):
    if isinstance(expr, And):
        return self.apply_and_absorption(expr)
    elif isinstance(expr, Or):
        return self.apply_or_absorption(expr)
    else:
        return expr

def apply_and_absorption(self, expr):
    lhs, rhs = expr.args
    if is_contradiction(lhs):
        return lhs
    elif is_contradiction(rhs):
        return rhs
    elif is_tautology(lhs):
        return rhs
    elif is_tautology(rhs):
        return lhs
    else:
        return expr

def apply_or_absorption(self, expr):
    lhs, rhs = expr.args
    if is_contradiction(lhs):
        return rhs
    elif is_contradiction(rhs):
        return lhs
    elif is_tautology(lhs):
        return lhs
    elif is_tautology(rhs):
        return rhs
    else:
        return expr

def is_contradiction(self, expr):
    return isinstance(expr, Not) and expr.args[0] == self

def is_tautology(self, expr):
    return expr == self
